/**
 * A canonical binding-override address, keyed by the registry binding
 * identity.
 *
 * Distinct from `ModeloEditScalarAddressV1`: a binding override addresses
 * `CalculationRevision.binding_overrides`, which is keyed by `BindingId`,
 * never `CasillaId` -- most overridable bindings (a fichero-BOE record-field
 * `manual_input` binding, most notably) have no casilla at all to address
 * through.
 */
export type ModeloEditBindingAddressV1 = {
  kind: "binding";
  binding_id: BindingId;
};

/**
 * The two distinct binding-override edit intents; address absence means
 * UNCHANGED.
 *
 * Both act on the `BindingId`-keyed binding overrides of the revision's
 * operator layer: `SET_OVERRIDE_VALUE` replaces the operator's override and
 * `REMOVE_OVERRIDE` withdraws it, so the binding's source tiers win again.
 */
export type ModeloEditBindingIntentKind =
  "set_override_value" | "remove_override";

/**
 * One offered choice: the stored code, never translated, and the catalogue id
 * of its word where it has one.
 *
 * A form's design can declare the blank itself as a choice, as an unmarked
 * checkbox: an empty `code` is that stated blank, which is neither an entry
 * that was never made nor a refused one.
 */
export type ModeloEditChoiceV1 = {
  code: string;
  word: string | null;
};

