/**
 * A casilla's corrected value on a declaration recorded as filed, read for its
 * amendment.
 *
 * Only an entry typed for a correction is addressed this way, and only a
 * preflight reads it: a correction is never an edit intent, so no apply or
 * surface entry takes this address.
 */
export type ModeloEditCorrectionAddressV1 = {
  kind: "correction";
  casilla_id: CasillaId;
};

/**
 * The natural-key address of one `ModeloDetailRow`, never position or a minted
 * id.
 *
 * `detail_row_kind` is the discriminated `ModeloDetailRow.row_type` value
 * (e.g. `"miembro"`, `"operador"`). `natural_key` is the row's own already-
 * declared identity field, joined with `|` for a compound key (M349
 * operador/rectificación key on `nif_comunitario|clave_operacion`, since one
 * counterparty can carry more than one operation type) -- never a minted or
 * positional identity. This mirrors the codebase's established whole-set-
 * replacement convention for repeating declared rows
 * (`RetencionObservationRepository.replace_observations`): rows are addressed
 * by the business key they already carry, and an absent key is sufficient to
 * express removal with no separate "explicitly deleted" axis, because a row
 * (unlike a scalar) has no ambiguous middle state between "declared" and
 * "absent".
 */
export type ModeloEditDetailRowAddressV1 = {
  kind: "detail_row";
  detail_row_kind: string;
  natural_key: string;
};

/**
 * The closed `ModeloDetailRow` edit intents, addressed by natural key.
 *
 * `MOVE_ROW` is deliberately NOT a member. A row's physical record occurrence
 * number in the exported fichero is NOT a function of caller-supplied order at
 * all: every row-producer resolver in `detail_record_bindings`
 * (`resolve_atribucion_binding_row_values`, `_build_related_party_rows`,
 * `_build_foreign_asset_rows`, and their siblings) sorts its rows by a content
 * key -- `(country_code, tax_id)` or equivalent -- BEFORE `enumerate(..., 1)`
 * assigns row indices, so two calls supplying the same rows in different
 * orders render byte-identical ficheros (each builder's sort is proven in `cad
 * rumo.domain.calculations.registry.tests.test_detail_record_row_builders`).
 * The AEAT diseno de registro for these record families identifies each
 * repeated record by its declared content (member/counterparty NIF, asset
 * identifier, clave/subclave) rather than by a required sequence -- there is
 * no "declared order" for AEAT to read or for a reorder to change.
 * Consistently, the calculation revision's content address is also order-BLIND
 * (`_canonical_detail_rows` sorts by `(row_type, nif-like)` specifically so
 * "operators can supply rows in any order"). A pure reorder therefore computes
 * the SAME revision id AND renders the SAME fichero bytes as the existing
 * revision, so the guarded compare-and-swap persistence layer's duplicate-
 * result branch would silently absorb it and return the existing revision --
 * the requested reorder would never actually persist, and even if it did
 * nothing observable would change. Building MOVE_ROW against the current
 * content-address shape would ship a control with no addressable effect.
 */
export type ModeloEditDetailRowIntentKind =
  "add_row" | "update_row" | "delete_row";

