/**
 * The closed repeatable-row edit intents; MOVE_ROW requires reorderable
 * groups.
 */
export type ModeloEditRowIntentKind =
  "add_row" | "update_row" | "delete_row" | "move_row";

/**
 * A canonical semantic scalar address, keyed by the registry casilla identity.
 */
export type ModeloEditScalarAddressV1 = {
  kind: "scalar";
  casilla_id: CasillaId;
};

/**
 * The three distinct scalar edit intents; address absence means UNCHANGED.
 *
 * Each acts on the casilla's entry in the revision's operator layer:
 * `SET_TYPED_VALUE` replaces the operator's value (and withdraws an earlier
 * clear), `CLEAR_DECLARED_VALUE` removes it and records an explicit clear when
 * no source feeds the casilla, and `RESTORE_SOURCE_VALUE` removes it without
 * recording a clear, so the source tiers win again. Withdrawing a binding
 * override is binding-addressed -- see `ModeloEditBindingIntentKind`.
 */
export type ModeloEditScalarIntentKind =
  "set_typed_value" | "clear_declared_value" | "restore_source_value";

/**
 * The edit contract's own schema identity: a compare-and-swap coordinate, not
 * a display fact.
 *
 * Deliberately its own type rather than a reuse of
 * `ModeloWorkspaceSchemaIdentityV1` -- the two types share a shape (an id, a
 * fingerprint, and a manifest digest) but not a meaning.
 * `completeness_manifest_digest` digests the registry's
 * `CalculationCompletenessManifest` (the required calculation-closure casilla
 * set: a TAX-SEMANTIC completeness declaration), so a compare-and-swap re-
 * check catches the registry's declared completeness rules changing between
 * admission and commit. The Workspace type's `field_manifest_digest` digests a
 * structurally unrelated concept -- the field-CLASSIFICATION manifest, a
 * deterministic walk over the public registry TYPE denominator for display
 * rendering. Sharing one field name would make two genuinely different values
 * compare unequal under one name.
 */
export type ModeloEditSchemaIdentityV1 = {
  schema_id: string;
  schema_fingerprint: ContentDigest;
  completeness_manifest_digest: ContentDigest;
};

/**
 * The compare-and-swap refusal naming every coordinate that disagreed.
 *
 * Writes nothing and settles the domain effect as `NONE`. Never silently
 * rebases, merges, or retries against a new baseline.
 */
export type ModeloEditStaleBaselineRefusalV1 = {
  kind: "stale_edit_baseline";
  edit_contract_version: 1;
  baseline_id: ModeloEditBaselineId;
  mismatching_coordinates: string[];
  responsible_owner: string;
  reconsideration_condition: string;
  recovery_action: ActionReference | null;
};

/**
 * One closed reason per intent kind this V1 executor cannot yet reach.
 *
 * Named for what capability is missing, never for the internal plan Step that
 * will supply it: a plan Step id is process metadata, and this reason ships
 * inside a public runtime contract. The Step-to-reason mapping is recorded
 * where cross-referencing code to project tracking belongs -- the Step Record
 * that implements each reason, never the reverse.
 */
export type ModeloEditUnsupportedIntentReason =
  | "add_row_not_yet_wired"
  | "update_row_not_yet_wired"
  | "delete_row_not_yet_wired"
  | "move_row_not_yet_wired"
  | "recalculate_not_yet_wired";

/**
 * A syntactically admitted intent this V1 executor cannot yet execute.
 *
 * Distinct from `ModeloEditDomainRefusalV1`'s `DISALLOWED_INTENT`: that code
 * means the baseline's permitted surface never admitted the address. This
 * refusal means the address and intent ARE admitted, but the calculation
 * boundary this executor delegates to has no input shape for this intent kind
 * yet, so a caller can tell a not-yet-built path from a genuinely invalid one.
 */
export type ModeloEditUnsupportedIntentRefusalV1 = {
  kind: "unsupported_intent";
  edit_contract_version: 1;
  address: ModeloEditAddressV1 | null;
  reason: ModeloEditUnsupportedIntentReason;
  responsible_owner: string;
  reconsideration_condition: string;
};

export type ModeloEditValueAddressV1 =
  | ModeloEditScalarAddressV1
  | ModeloEditBindingAddressV1
  | ModeloEditCorrectionAddressV1;

/**
 * Which engine input channel carries the value; `UNAVAILABLE` means none does
 * yet.
 */
export type ModeloEditValueChannel = "decimal" | "text" | "unavailable";

/**
 * The kind of value an address takes, independent of how it is written.
 */
export type ModeloEditValueFamily =
  "decimal" | "integer" | "boolean" | "date" | "text";

/**
 * Everything an editor and the parser need to read one address's value;
 * carries no value.
 *
 * `data_type` is the registry token of the address (a casilla data type, or a
 * binding value data type). `minimum` and `maximum` are canonical decimal
 * text; `minimum_value` and `maximum_value` read them. `max_fraction_digits`
 * is `None` when the registry states no precision. `pattern` is the registry-
 * declared text pattern, used for validation and never shown.
 * `constraints_declared` is false for the common case of an address whose
 * registry row states no constraint at all, which an editor shows as such.
 */
export type ModeloEditValueGrammarV1 = {
  data_type: string;
  family: ModeloEditValueFamily;
  channel: ModeloEditValueChannel;
  max_fraction_digits: number | null;
  sign: "any" | "non_negative" | "non_positive";
  minimum: string | null;
  maximum: string | null;
  choices: ModeloEditChoiceV1[] | null;
  min_length: number | null;
  max_length: number | null;
  pattern: string | null;
  ratio_unit: ModeloEditRatioUnit | null;
  money_operand_bound: boolean;
  required: boolean;
  constraints_declared: boolean;
};

/**
 * Minimal refusal produced before a rejected request target is parsed.
 */
export type ModeloEditVersionRefusalV1 = {
  kind: "unsupported_version";
  requested_version: number | null;
  supported_version: 1;
};

